// Minimal reimplementation of Python's argparse behavior (subset used by test10).
// Supports: required string options, "--opt value" and "--opt=value" forms,
// -h/--help, usage/error reporting with argparse's exact exit codes.

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog;
    // -h/--help is added automatically, exactly like argparse.
    this.actions = [
      { flags: ['-h', '--help'], dest: 'help', isHelp: true, required: false },
    ];
  }

  addArgument(flag, { type = 'str', required = false } = {}) {
    const dest = flag.replace(/^--?/, '');
    this.actions.push({
      flags: [flag],
      dest,
      metavar: dest.toUpperCase(),
      type,
      required,
      isHelp: false,
    });
  }

  _formatUsage() {
    const parts = [];
    for (const action of this.actions) {
      if (action.isHelp) {
        parts.push('[-h]');
      } else if (action.required) {
        parts.push(`${action.flags[0]} ${action.metavar}`);
      } else {
        parts.push(`[${action.flags[0]} ${action.metavar}]`);
      }
    }
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  _formatHelp() {
    const lines = [this._formatUsage(), '', 'options:'];
    const invocations = this.actions.map((action) =>
      action.isHelp ? '-h, --help' : `${action.flags[0]} ${action.metavar}`
    );
    const indent = 2;
    const maxLen = Math.max(...invocations.map((s) => s.length + indent));
    const helpPosition = Math.min(maxLen + 2, 24 + 2);
    this.actions.forEach((action, i) => {
      const header = ' '.repeat(indent) + invocations[i];
      if (action.isHelp) {
        const text = 'show this help message and exit';
        lines.push(header + ' '.repeat(helpPosition - header.length) + text);
      } else {
        lines.push(header);
      }
    });
    return lines.join('\n');
  }

  error(message) {
    process.stderr.write(this._formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  parseArgs(argv) {
    const values = {};
    const extras = [];
    const byFlag = new Map();
    for (const action of this.actions) {
      for (const flag of action.flags) byFlag.set(flag, action);
    }

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      let flag = token;
      let inlineValue = null;
      if (token.startsWith('--') && token.includes('=')) {
        const idx = token.indexOf('=');
        flag = token.slice(0, idx);
        inlineValue = token.slice(idx + 1);
      }
      const action = byFlag.get(flag);
      if (action) {
        if (action.isHelp) {
          process.stdout.write(this._formatHelp() + '\n');
          process.exit(0);
        }
        let value = inlineValue;
        if (value === null) {
          const next = argv[i + 1];
          // An option-looking token cannot be consumed as a value.
          if (next === undefined || (next.startsWith('-') && next !== '-')) {
            this.error(`argument ${action.flags[0]}: expected one argument`);
          }
          value = next;
          i++;
        }
        values[action.dest] = value;
      } else {
        extras.push(token);
      }
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const missing = this.actions
      .filter((a) => !a.isHelp && a.required && !(a.dest in values))
      .map((a) => a.flags[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return values;
  }
}

// Job class mirroring the observable behavior of Python's schedule.Job.

export class ScheduleValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ScheduleValueError';
  }
}

export class Job {
  constructor(interval, scheduler) {
    this.interval = interval;
    this.scheduler = scheduler;
    this.unit = null;
    this.atTime = null;
    this.jobFunc = null;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  at(timeStr) {
    if (!/^\d{2}:\d{2}(:\d{2})?$/.test(timeStr)) {
      throw new ScheduleValueError(
        'Invalid time format for a daily job (valid format is HH:MM(:SS)?)'
      );
    }
    const parts = timeStr.split(':').map(Number);
    const [hour, minute] = parts;
    const second = parts.length === 3 ? parts[2] : 0;
    if (hour < 0 || hour > 23) {
      throw new ScheduleValueError(
        'Invalid number of hours (0-23) for a daily job'
      );
    }
    if (minute < 0 || minute > 59) {
      throw new ScheduleValueError(
        'Invalid number of minutes (0-59) for a daily job'
      );
    }
    if (second < 0 || second > 59) {
      throw new ScheduleValueError(
        'Invalid number of seconds (0-59) for a daily job'
      );
    }
    this.atTime = timeStr;
    return this;
  }

  do(jobFunc) {
    this.jobFunc = jobFunc;
    this.scheduler.jobs.push(this);
    return this;
  }

  toString() {
    return (
      `Job(interval=${this.interval}, unit=${this.unit}, ` +
      `do=<lambda>, args=(), kwargs={})`
    );
  }
}

// Scheduler mirroring the observable behavior of Python's schedule module
// (the default scheduler and its module-level convenience functions).

import { Job, ScheduleValueError } from './job.mjs';

export { ScheduleValueError };

export class Scheduler {
  constructor() {
    this.jobs = [];
  }

  every(interval = 1) {
    return new Job(interval, this);
  }

  cancelJob(job) {
    const index = this.jobs.indexOf(job);
    if (index !== -1) {
      this.jobs.splice(index, 1);
    }
  }

  clear() {
    this.jobs = [];
  }

  getJobs() {
    return [...this.jobs];
  }
}

const defaultScheduler = new Scheduler();

export function every(interval = 1) {
  return defaultScheduler.every(interval);
}

export function cancelJob(job) {
  defaultScheduler.cancelJob(job);
}

export function clear() {
  defaultScheduler.clear();
}

export function getJobs() {
  return defaultScheduler.getJobs();
}

import path from 'node:path';
import { ArgumentParser } from './lib/argparse.mjs';
import {
  every,
  cancelJob,
  clear,
  getJobs,
  ScheduleValueError,
} from './lib/scheduler.mjs';

const parser = new ArgumentParser({ prog: path.basename(process.argv[1]) });
parser.addArgument('--a', { type: 'str', required: true });
parser.addArgument('--b', { type: 'str', required: true });
parser.addArgument('--c', { type: 'str', required: true });
parser.addArgument('--d', { type: 'str', required: true });
const args = parser.parseArgs(process.argv.slice(2));

try {
  const job1 = every().seconds.do(() => null); // 创建秒级作业
  console.log(String(job1));
  cancelJob(job1); // 取消作业1
  console.log(getJobs().length);
  const job2 = every().minutes.do(() => null); // 创建分钟作业
  console.log(String(job2));
  const job3 = every().hours.do(() => null); // 创建小时作业
  console.log(String(job3));
  clear(); // 清除所有作业
  console.log(getJobs().length);
  const job4 = every().days.at(args.a).do(() => null); // 创建每日作业
  console.log(String(job4));
  const job5 = every().weeks.do(() => null); // 创建每周作业
  console.log(String(job5));
  console.log(getJobs().length);
} catch (err) {
  if (err instanceof ScheduleValueError) {
    // Mirror the Python traceback emitted for an invalid daily time.
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test10.py", line 21, in <module>\n');
    process.stderr.write('  File "schedule/__init__.py", line 514, in at\n');
    process.stderr.write(`schedule.ScheduleValueError: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}

