  const parts = timeStr.split(':').map(Number);
  const [hour] = parts;
  if (hour < 0 || hour > 23) {
    throw new ScheduleValueError(
      'Invalid number of hours ({} is not between 0 and 23)',
      547
    );
  }
  this.atTime = timeStr;
  return this;
}

