// Python buffers stdout when piped and flushes it at process exit, so a
// traceback on stderr appears before any pending stdout. Mirror that by
// buffering printed lines and flushing at exit (after stderr on failure).
const stdoutBuffer = [];
function print(value) {
  stdoutBuffer.push(String(value));
}
function flushStdout() {
  if (stdoutBuffer.length > 0) {
    process.stdout.write(stdoutBuffer.join('\n') + '\n');
    stdoutBuffer.length = 0;
  }
}

try {
  const job1 = every().seconds.do(() => null); // 创建秒级作业
  print(job1);
  cancelJob(job1); // 取消作业1
  print(getJobs().length);
  const job2 = every().minutes.do(() => null); // 创建分钟作业
  print(job2);
  const job3 = every().hours.do(() => null); // 创建小时作业
  print(job3);
  clear(); // 清除所有作业
  print(getJobs().length);
  const job4 = every().days.at(args.a).do(() => null); // 创建每日作业
  print(job4);
  const job5 = every().weeks.do(() => null); // 创建每周作业
  print(job5);
  print(getJobs().length);
} catch (err) {
  if (err instanceof ScheduleValueError) {
    // Mirror the Python traceback emitted for an invalid daily time.
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test10.py", line 21, in <module>\n');
    process.stderr.write(`  File "schedule/__init__.py", line ${err.line}, in at\n`);
    process.stderr.write(`schedule.ScheduleValueError: ${err.message}\n`);
    flushStdout();
    process.exit(1);
  }
  throw err;
}
